import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        char[] digits = new char[n];
        for (int i = 0; i < n; i++) {
            digits[i] = (char) ('0' + scanner.nextInt());
        }

        for (int len = 1; len <= n; len++) {
            StringBuilder current = new StringBuilder(len);
            for (int i = 0; i < len; i++) {
                current.append(digits[i]);
            }

            int idx = len;
            boolean valid = true;

            while (idx < n) {
                increment(current);
                int curLen = current.length();
                if (idx + curLen > n) {
                    valid = false;
                    break;
                }

                for (int j = 0; j < curLen; j++) {
                    if (digits[idx + j] != current.charAt(j)) {
                        valid = false;
                        break;
                    }
                }

                if (!valid) {
                    break;
                }

                idx += curLen;
            }

            if (valid && idx == n) {
                // Encontrado o menor A
                for (int i = 0; i < len; i++) {
                    System.out.print(digits[i]);
                }
                System.out.println();
                return;
            }
        }
    }

    private static void increment(StringBuilder sb) {
        int i = sb.length() - 1;
        while (i >= 0 && sb.charAt(i) == '9') {
            sb.setCharAt(i, '0');
            i--;
        }
        if (i >= 0) {
            sb.setCharAt(i, (char) (sb.charAt(i) + 1));
        } else {
            sb.insert(0, '1');
        }
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
